function getDatarobotTranslation(key, lang) {
    if (datarobotTranslations[lang] && datarobotTranslations[lang][key]) {
        return datarobotTranslations[lang][key];
    }
    if (datarobotTranslations.en && datarobotTranslations.en[key]) {
        return datarobotTranslations.en[key];
    }
    return null;
}

function applyDatarobotTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.datarobot.')) {
            const translation = getDatarobotTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyDatarobotTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyDatarobotTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyDatarobotTranslations(currentLang);
}


